const BluishGreyBaseUniformColour = '#94a5bd;';
const BeigeBaseUniformColour = '#e0c8b5;';

export class TmpUniformPack extends BaseNeckProvider implements IUniformPack {
  getUniformSwatches(species: Species) {
    return [
      new Swatch(
        BodyType.AverageMale,
        'Average Male',
        (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              UniformVariantType.Base,
              BodyType.AverageMale,
            ),
            BodyType.AverageMale,
            token,
          ),
        'BodyType.averageMale',
      ),
      new Swatch(
        BodyType.AverageFemale,
        'Average Female',
        (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              UniformVariantType.Base,
              BodyType.AverageFemale,
            ),
            BodyType.AverageFemale,
            token,
          ),
        'BodyType.averageFemale',
      ),
    ];
  }

  getUniformAndVariantBody(token: TokenModel) {
    return this.getUniformAndVariantByBodyType(
      token,
      token.variant,
      token.bodyType,
    );
  }

  getUniformAndVariantByBodyType(
    token: TokenModel,
    variant: UniformVariantType,
    bodyType: BodyType,
  ) {
    let result = '';
    switch (bodyType) {
      case BodyType.AverageMale: {
        result = TmpUniforms.averageMaleBody;
        break;
      }
      case BodyType.AverageFemale:
        result = TmpUniforms.averageFemaleBody;
        break;
      default:
    }
    return (
      this.getNeck(
        bodyType,
        token.skinColor,
        token.species,
        UniformEra.TheMotionPicture,
      ) +
      result
        .replace(DefaultRed, token.divisionColor)
        .replace(SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX, token.skinColor)
    );
  }

  getUniformVariantSwatches(token: TokenModel) {
    return [];
  }

  getRankSwatches() {
    return [
      new Swatch(
        Rank.None,
        'None',
        (token) => TmpUniformPack.decorateRankSwatch('', Rank.None, token),
        'Rank.none.name',
      ),
      new Swatch(
        Rank.Ensign,
        'Ensign',
        (token) =>
          TmpUniformPack.decorateRankSwatch(
            TmpRankIndicators.swatches.Ensign.replace(BluishGreyBaseUniformColour, this.getUniformBaseColour(token)),
            Rank.Ensign,
            token,
          ),
        'Rank.ensign.name',
      ),
      new Swatch(
        Rank.LieutenantJG,
        'Lieutenant J.G.',
        (token) =>
          TmpUniformPack.decorateRankSwatch(
            TmpRankIndicators.swatches.LieutenantJG.replace(BluishGreyBaseUniformColour, this.getUniformBaseColour(token)),
            Rank.LieutenantJG,
            token,
          ),
        'Rank.lieutenantJG.name',
      ),
      new Swatch(
        Rank.Lieutenant,
        'Lieutenant',
        (token) =>
          TmpUniformPack.decorateRankSwatch(
            TmpRankIndicators.swatches.Lieutenant.replace(BluishGreyBaseUniformColour, this.getUniformBaseColour(token)),
            Rank.Lieutenant,
            token,
          ),
        'Rank.lieutenant.name',
      ),
      new Swatch(
        Rank.LtCommander,
        'Lt. Commander',
        (token) =>
          TmpUniformPack.decorateRankSwatch(
            TmpRankIndicators.swatches.LtCommander.replace(BluishGreyBaseUniformColour, this.getUniformBaseColour(token)),
            Rank.LtCommander,
            token,
          ),
        'Rank.ltCommander.name',
      ),
      new Swatch(
        Rank.Commander,
        'Commander',
        (token) =>
          TmpUniformPack.decorateRankSwatch(
            TmpRankIndicators.swatches.Commander.replace(BluishGreyBaseUniformColour, this.getUniformBaseColour(token)),
            Rank.Commander,
            token,
          ),
        'Rank.commander.name',
      ),
      new Swatch(
        Rank.Captain,
        'Captain',
        (token) =>
          TmpUniformPack.decorateRankSwatch(
            TmpRankIndicators.swatches.Captain.replace(BluishGreyBaseUniformColour, this.getUniformBaseColour(token)),
            Rank.Captain,
            token,
          ),
        'Rank.captain.name',
      ),
    ];
  }

  getRankIndicator(token: TokenModel) {
    return '';
  }

  private getUniformBaseColour(token: TokenModel) {
    let baseColour = BluishGreyBaseUniformColour;
    if (token.variant === UniformVariantType.Variant1) {
      baseColour = BeigeBaseUniformColour;
    }
    return baseColour;
  }

  getRankBorderIndicator(token: TokenModel) {
    let result = '';
    switch (token.rankIndicator) {
      case Rank.Ensign:
        result = TosEnsignRankBorder;
        break;
      case Rank.LieutenantJG:
        result = TosLieutenantJGBorder;
        break;
      case Rank.Lieutenant:
        result = TosLieutenantBorder;
        break;
      case Rank.LtCommander:
        result = TosLtCommanderBorder;
        break;
      case Rank.Commander:
        result = TosCommanderBorder;
        break;
      case Rank.Captain:
        result = TosCaptainBorder;
        break;
      default:
    }
    return result.replace(BluishGreyBaseUniformColour, this.getUniformBaseColour(token));
  }

  getBorderColor(token: TokenModel) {
    return token.divisionColor;
  }

  getRankBorderDefinitions(token: TokenModel, bordered: boolean) {
    return '';
  }

  static decorateRankSwatch(
    svg: string,
    rankIndicator: Rank,
    token: TokenModel,
  ) {
    return (
      `<svg viewBox="0 0 80 80" version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
            <defs>
                <clipPath id="rankClipPath` +
      rankIndicator +
      `">
                    <circle cx="40" cy="40" r="40" fill="#ffffff" />
                </clipPath>
            </defs>
            <g clip-path="url(#rankClipPath` +
      rankIndicator +
      `">
                <g transform="translate(-65, -318)">` +
      svg.replace(DefaultRed, '#94a5bd') +
      `</g>
        + </g>
        </svg>`
    );
  }

  getBorderLogo(token: TokenModel): string {
    return TmpDelta.replace(DefaultRed, token.divisionColor);
  }

  isDivisionColorSupported(token: TokenModel): boolean {
    return true;
  }

  getRankIndicatorExtra(token: TokenModel): string {
    return '';
  }
}
